#!/bin/sh
# Generated by forge. Stop hook: runs .forge/check.sh on what changed during this
# turn (--turn, against the snapshot taken by turn-start.sh), or on every
# uncommitted change when there is no snapshot (--changed); hands over after 3 blocks.
# A tree that failed is not checked again: the same reason is given until it changes.
# Advice alone (check.sh exits 4) blocks once; the same tree then passes.
# Tests that fail at the start of the turn too block once with what to do; on the same
# tree again the stop is allowed and the user is told they could not be verified.
# this script's directory, absolute (builtins)
case $0 in */*) dir=${0%/*} ;; *) dir=. ;; esac
case $dir in /*) ;; *) dir=$PWD/$dir ;; esac
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
[ -f .forge/check.sh ] || { printf '{"decision":"block","reason":"forge:forge/integrity .forge/check.sh is missing (run forge apply)"}\n'; exit 0; }
forge_state_dir

counter=$FORGE_STATE/$(session_id).blocks
snap=$(turn_dir)
hash=$(tree_hash)
if [ -f "$snap/head" ]; then
  # unchanged since the prompt (same tree, same HEAD): whatever is dirty is not this turn's work
  [ "$hash" = "$(cat "$snap/tree" 2>/dev/null)" ] && [ "$(git rev-parse -q --verify HEAD 2>/dev/null)" = "$(cat "$snap/head")" ] && exit 0
  passed=$snap/pass
  failed=$snap/fail
  hash="$hash $(git rev-parse -q --verify HEAD 2>/dev/null)"
  set -- --turn "$snap"
else
  passed=$FORGE_STATE/last-pass
  failed=$FORGE_STATE/last-fail
  set -- --changed
fi
[ "$hash" = "$(cat "$passed" 2>/dev/null)" ] && exit 0

# Only tests that also fail at the start of the turn, and the agent stopped again
# without changing anything: allowed, and the user is told what was not verified.
if [ "$hash" = "$(cat "$failed" 2>/dev/null)" ] && [ -s "$failed.unverified" ]; then
  msg=$(awk -F '\t' '
    $1 == "test" { t[++n] = substr($0, 6) } $1 == "env" { e[++m] = $2 }
    END {
      printf "forge: %d test(s) could not be verified: they fail with and without Claude'"'"'s change", n
      if (m) { printf ", and their errors look environmental: "; for (i = 1; i <= m; i++) printf "%s%s", (i > 1 ? "; " : ""), e[i] }
      printf ". Not verified: "
      for (i = 1; i <= n && i <= 10; i++) printf "%s%s", (i > 1 ? "; " : ""), t[i]
      if (n > 10) printf "; and %d more", n - 10
      printf ". Run them once the environment is set up."
    }' "$failed.unverified" | json_escape)
  printf '%s\n' "$hash" > "$passed"
  rm -f "$counter" "$failed" "$failed.reason" "$failed.unverified"
  printf '{"systemMessage":"%s"}\n' "$msg"
  exit 0
fi

count=$(cat "$counter" 2>/dev/null)
case $count in ''|*[!0-9]*) count=0 ;; esac
if [ "$count" -ge 3 ]; then
  rm -f "$counter"
  printf '{"systemMessage":"forge: check failed 3 times. Handing over to you."}\n'
  exit 0
fi

# the tree as it is now (after formatters ran)
now_tree() { if [ -f "$snap/head" ]; then printf '%s %s\n' "$(tree_hash)" "$(git rev-parse -q --verify HEAD 2>/dev/null)"; else tree_hash; fi; }
# block [<first line>]: blocks with the reason in $failed.reason
block() {
  printf '%s\n' "$((count + 1))" > "$counter"
  printf '{"decision":"block","reason":"%s"}\n' "$({ [ -z "${1:-}" ] || printf '%s\n' "$1"; cat "$failed.reason"; } | json_escape)"
  exit 0
}

# Same tree as the last failed check: the checks give the same result on the same
# tree, so it is given again without re-running them (a test suite can take minutes).
if [ "$hash" = "$(cat "$failed" 2>/dev/null)" ] && [ -f "$failed.reason" ]; then
  block 'forge: nothing changed in the working tree since this check failed, so it was not run again (it runs again once a file changes):'
fi

rm -f "$failed.unverified"
# one time budget for the whole check, under the hook's 600 s timeout (a stopped hook
# blocks nothing): each check gets at most what is left of it
FORGE_BUDGET=${FORGE_STOP_BUDGET:-540}
case $FORGE_BUDGET in ''|*[!0-9]*) FORGE_BUDGET=540 ;; esac
FORGE_DEADLINE=$(($(date +%s) + FORGE_BUDGET))
export FORGE_BUDGET FORGE_DEADLINE
# FORGE_FOR_AGENT: the reason goes to Claude, without notes about missing or limited tools
out=$(FORGE_FOR_AGENT=1 FORGE_UNVERIFIED=$failed.unverified sh .forge/check.sh "$@" 2>&1)
rc=$?
if [ "$rc" -eq 0 ]; then
  now_tree > "$passed"
  rm -f "$counter" "$failed" "$failed.reason" "$failed.unverified"
  exit 0
fi
# exit 3: the only failures are tests that fail at the start of the turn too
[ "$rc" -eq 3 ] || rm -f "$failed.unverified"
# the failures first, then the "skipped", "ok for" and "accepted" notes sorted by rule
# (checks print them in run order, which differs when advice is deferred, so the same
# tree gives the same reason); at most 40 lines and 6000 characters, so the reason
# stays short when Claude Code shows it
note='^forge:[^ ]+ (skipped:|ok for |accepted:|not enforced)'
{ printf '%s\n' "$out" | grep -Ev "$note"; printf '%s\n' "$out" | grep -E "$note" | LC_ALL=C sort; } \
  | awk '{ c += length($0) + 1 } NR <= 40 && c <= 6000' > "$failed.reason"
# exit 4: advice only (§10.7). It is given once: the same tree then passes, so it is
# recorded as passing (the checks did pass) and not as failing. Any other failure is
# recorded as failing, advice included, and replayed until the tree changes.
if [ "$rc" -eq 4 ]; then
  now_tree > "$passed"
  rm -f "$failed"
else
  now_tree > "$failed"
fi
block
